    video_links = soup.find_all('a')
    relevant_links = []

    for link in video_links:
        href = link.get('href', '')
        title = link.get_text('', strip=True)
        if 'Cheater' in title and 'CFM' in title:
            relevant_links.append((title, href))

    if relevant_links:
        print('Found potential videos:')
        for title, href in relevant_links[:5]:
            print(f'- {title} - {href}')
    else:
        print('No direct CFM results found on YouTube')

except Exception as e:
    print(f'Search error: {e}')
